CREATE COLUMN TABLE "TEST_AP"."OIST" ("AbsEntry" INTEGER CS_INT NOT NULL , "InstrCode" NVARCHAR(2) NOT NULL , "InstrDespt" NVARCHAR(128), "IsCancel" NVARCHAR(1) DEFAULT 'N' NOT NULL , PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OIST_CODE" ON "TEST_AP"."OIST" ( "InstrCode" ASC, "IsCancel" ASC )